pub fn reader(original: &str, old: &str) -> String {
    assert_eq!(
        original.matches(old).count(),
        1,
        "exact preservation reader"
    );
    original.replacen(
        old,
        &old.replace(
            "std::fs::read_to_string",
            "crate::runtime_io::read_to_string",
        ),
        1,
    )
}
